function calendarView(sales){const month=state.calendarMonth?new Date(state.calendarMonth+'-01T12:00:00'):new Date(),year=month.getFullYear(),monthIndex=month.getMonth(),first=new Date(year,monthIndex,1),last=new Date(year,monthIndex+1,0),offset=(first.getDay()+6)%7,days={};for(const sale of sales){const key=String(sale.date||sale.createdAt||sale.created_date||'').slice(0,10);if(!key)continue;const lines=Array.isArray(sale.items)?sale.items:[],profit=Number(sale.gross_profit_total)||lines.reduce((n,x)=>n+(Number(x.total_amount)||0)-(Number(x.company_price_total)||Number(x.company_price)||0),0);days[key]??={revenue:0,count:0,profit:0};days[key].revenue+=Number(sale.sales_total||sale.total)||0;days[key].count++;days[key].profit+=profit;}const cells=[];for(let i=0;i<offset;i++)cells.push('<div class="calendar-cell empty"></div>');for(let day=1;day<=last.getDate();day++){const date=year+'-'+String(monthIndex+1).padStart(2,'0')+'-'+String(day).padStart(2,'0'),v=days[date]||{revenue:0,count:0,profit:0};cells.push(`<button class="calendar-cell ${v.count?'has-sales':''}" data-calendar-day="${date}"><strong>${day}</strong><span>${money(v.revenue)} DZD</span><small>${v.count} ticket(s)</small><small>Marge ${money(v.profit)}</small></button>`);}return head('Calendrier des Ventes','Chiffre d’affaires, tickets et marge par jour')+`<div class="panel"><div class="calendar-toolbar"><button class="btn" data-calendar-month="-1">←</button><h3>${month.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h3><button class="btn" data-calendar-month="1">→</button></div><div class="calendar-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>'<div class="calendar-weekday">'+x+'</div>').join('')}${cells.join('')}</div></div>`;}
async function zakatView(){let stockValue=0,stockCount=0;try{const items=await loadAllCatalogueItems(true);stockValue=items.reduce((sum,item)=>{const qty=Number(item.available_quantity??item.quantity??item.items_quantity??0),price=Number(item.selling_price??item.selling_price1??item.items_selling_price??0);if(!Number.isFinite(qty)||!Number.isFinite(price)||qty<=0||price<=0)return sum;stockCount+=qty;return sum+price*qty;},0);stockValue=Math.round(stockValue*100)/100;}catch(error){console.warn('[V2] Zakat stock valuation unavailable:',error.message);}state.zakatStockValue=stockValue;return head('Calculateur de Zakat','Estimation indicative · saisissez les valeurs réelles de votre boutique')+`<section class="panel" id="zakat-form"><div class="form-grid"><div class="form-field"><label>Prix de l’or par gramme (DZD)</label><input class="field" id="zakat-gold-price" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>Espèces disponibles (DZD)</label><input class="field" id="zakat-cash" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>Valeur du stock (Prix 1 × quantité) · DZD</label><input class="field" id="zakat-stock" type="number" min="0" step=".01" value="${stockValue.toFixed(2)}" readonly><small class="muted small">Calcul automatique · ${stockCount.toLocaleString('fr-FR')} unité(s) en stock valorisée(s) au prix de vente 1</small></div><div class="form-field"><label>Créances recouvrables (DZD)</label><input class="field" id="zakat-receivables" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>Dettes et passifs (DZD)</label><input class="field" id="zakat-liabilities" type="number" min="0" step=".01" value="0"></div><div class="form-field full"><label><input type="checkbox" id="zakat-hawl"> Condition du hawl satisfaite</label></div></div><div class="stats"><div class="stat"><div class="label">Nissab (85 g d’or)</div><div class="value" id="zakat-nissab">0,00 DZD</div></div><div class="stat"><div class="label">Patrimoine net estimé</div><div class="value" id="zakat-net">0,00 DZD</div></div><div class="stat"><div class="label">Zakat estimée (2,5 %)</div><div class="value" id="zakat-due">0,00 DZD</div></div></div><p class="muted small">Calcul indicatif : max(0, espèces + stock + créances − passifs). La Zakat est estimée à 2,5 % si le patrimoine net atteint le Nissab et si le hawl est satisfait. Le prix de l’or et les montants doivent être renseignés à partir de données réelles. Ceci n’est pas un avis religieux.</p></section>`;}
function genericData(d,title){const obj=Array.isArray(d)?d:[d];return head(title,'Réponse du service POSNIC')+`<div class="panel"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(obj,null,2))}</pre></div>`;}
