 const allowedFonts={Arial:'Arial, sans-serif',Georgia:'Georgia, serif',Verdana:'Verdana, sans-serif',Tahoma:'Tahoma, sans-serif',monospace:'monospace','Courier New':'Courier New, monospace','Trebuchet MS':'Trebuchet MS, sans-serif','Segoe UI':'Segoe UI, sans-serif',Impact:'Impact, sans-serif','Franklin Gothic Medium':'Franklin Gothic Medium, sans-serif','Lucida Console':'Lucida Console, monospace','Times New Roman':'Times New Roman, serif'};
 const source=Array.isArray(layout?.elements)?layout.elements:[];
 const mapType=e=>({header:'store',address:'store',date:'field',ticket:'field',cashier:'field',customer:'field',phone:'field',note:'field',footer:'text',custom:'text',whatsapp:'field'}[e.type]||e.type);
