  let type=mapType(e),block={id:String(e.id||('v2-'+index)).replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,60),type,align:['left','center','right'].includes(e.align)?e.align:'left',x:Math.max(-250,Math.min(300,Number(e.x)||0)),y:Math.max(-1200,Math.min(8000,(Number(e.y)||0)*height/100)),w:Math.max(2,Math.min(250,Number(e.w)||70)),h:Math.max(8,Math.min(2000,(Number(e.h)||8)*height/100)),rotation:((Number(e.rotation)||0)+180)%360-180};
