function recentSaleItems(sale){
 const candidates=[sale?.items,sale?.itemsale,sale?.products,sale?.sale_items,sale?.order_items,sale?.details,sale?.lines,sale?.saleItems];
 let lines=[];for(const source of candidates){lines=rowsOf(source);if(lines.length)break;}
 if(!lines.length)return '<div class="recent-sale-items empty-items">Détail des articles indisponible.</div>';
 return '<div class="recent-sale-items"><div class="recent-sale-items-heading">'+lines.length+' article(s)</div><div class="recent-sale-item-list">'+lines.map(line=>{
  const item=line.item_id&&typeof line.item_id==='object'?line.item_id:(line.item&&typeof line.item==='object'?line.item:null);
  const name=line.item_name||line.name||line.product_name||line.article_name||item?.name||line.product?.name||'Article';
  const qty=Number(line.item_quantity??line.quantity??line.qty??line.qte??1)||1;
  const unit=Number(line.sale_inline_item_price??line.item_price??line.unit_price??line.selling_price??line.price??0)||0;
  const rawTotal=line.total_amount??line.item_price_total??line.line_total??line.subtotal??line.total;
  const lineTotal=rawTotal===undefined?unit*qty:(Number(rawTotal)||0);
  return '<div class="recent-sale-item-line"><b>'+esc(name)+'</b><small> × '+qty+' · '+money(lineTotal)+' DZD</small></div>';
 }).join('')+'</div></div>';
}
