async function uniqueItemBarcode(){for(let i=0;i<40;i++){const code=String(1000000+crypto.getRandomValues(new Uint32Array(1))[0]%9000000);const found=rowsOf(await get('v2/items/fast-search',{q:code,limit:10,page:1}).catch(()=>[]));if(!found.some(x=>String(x.barcode_id||'')===code))return code;}throw new Error('Impossible de générer un code-barres unique.');}
